package ama.config.json;
import ama.model.*;import ama.canonical.*;import ama.minutes.contract.ContractValues;import org.junit.jupiter.api.Test;import java.nio.file.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static ama.config.json.Task09ControlledProtocolTest.*;import static ama.canonical.CanonicalValue.*;
class Task09Fix01ProviderAdmissionTest extends Task09ControlledEnvelopeStoreTest {
 AutoCloseable bounded()throws Exception{var c=ControlledMinutesProviderStore.class.getDeclaredConstructor(Path.class,String.class,int.class);c.setAccessible(true);return (AutoCloseable)c.newInstance(dir,"CONTROLLED_INSTALLATION",2);}
 Map<String,String> files()throws Exception{var m=new TreeMap<String,String>();try(var stream=Files.walk(dir)){for(var p:stream.filter(Files::isRegularFile).toList())m.put(dir.relativize(p).toString(),sha(Files.readAllBytes(p)));}return m;}
 Wire changed(boolean newInput)throws Exception{var w=wire();var body=(ObjectValue)BoundedModelJson.parse(w.body(),ControlledMinutesProtocol.MAX_REQUEST);var envelope=w.envelope();body=replace(body,"executionId",string(UUID.randomUUID().toString()));if(newInput){String input=UUID.randomUUID().toString();var b=ama.config.WireValues.fields(body,"protocolVersion","logicalBusinessKey","logicalRequestHash","executionRequestHash","executionId","executionNo","payloadSha256","payload");var payload=(ObjectValue)b.get("payload");var manifest=(ObjectValue)ama.config.WireValues.fields(payload,"protocolVersion","modelIdentity","parameters","instructionText","inputManifest","transcript","template","pinnedElements","exclusions").get("inputManifest");manifest=replace(manifest,"inputId",string(input));payload=replace(payload,"inputManifest",manifest);String fp=new CanonicalValueCodec().sha256(ContractValues.envelope("ama.generation-input.v2","GENERATION_INPUT",manifest),RawHashChainTest.GRAPH.canonical(),()->false),ph=sha(json(payload));envelope=replace(replace(replace(replace(envelope,"inputId",string(input)),"logicalBusinessKey",string("minutes:"+input)),"inputFingerprint",string(fp)),"payloadSha256",string(ph));String hash=new CanonicalValueCodec().sha256(ContractValues.envelope("ama.minutes-model-request.v1","MODEL_REQUEST",envelope),RawHashChainTest.GRAPH.canonical(),()->false);body=replace(replace(replace(replace(replace(body,"payload",payload),"payloadSha256",string(ph)),"logicalBusinessKey",string("minutes:"+input)),"logicalRequestHash",string(hash)),"executionRequestHash",string(hash));}var next=new Wire(json(body),header(envelope),envelope);ControlledMinutesProtocol.verify(next.body(),next.header());return next;}
 @Test void conflictingFreshExecutionsNeverWriteAnyDurableFile()throws Exception{try(var s=bounded()){reserve(s,wire());var before=files();for(int n=0;n<3;n++){var w=changed(false);assertThrows(RuntimeException.class,()->reserve(s,w));assertEquals(before,files());}}}
 @Test void capacityRejectsBeforeFilesAndAcceptedMappingsSurviveRestart()throws Exception{var first=wire();try(var s=bounded()){reserve(s,first);reserve(s,changed(true));var before=files();var excess=changed(true);assertThrows(Exception.class,()->reserve(s,excess));assertEquals(before,files());}try(var s=bounded()){assertEquals(lookup(s),reserve(s,first));var before=files();var excess=changed(true);assertThrows(Exception.class,()->reserve(s,excess));assertEquals(before,files());}}
 @Test void unjournaledCrashTemporaryConsumesFiniteAdmissionWithoutCleanup()throws Exception{try(var s=bounded()){reserve(s,wire());}Files.write(dir.resolve("requests/pending-crash-fixture.bin"),new byte[]{9});try(var s=bounded()){var before=files();var next=changed(true);assertThrows(Exception.class,()->reserve(s,next));assertEquals(before,files());assertNotNull(lookup(s));}}
}
